const normalize = (text: string): string => text.replace(/\s+/g, '').toLowerCase();

const dedupeByQuestion = (problems: GeneralProblem[]): GeneralProblem[] => {
  const seen = new Set<string>();
  return problems.filter((problem) => {
    const key = normalize(problem.question);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const getSourceCandidates = (mode: string, sourceMode: string, current: GeneralProblem[]): GeneralProblem[] => {
  const filter = SCIENCE_UNIT_SOURCE_FILTERS[mode];
  const source = SOURCE_MODE_DATA[sourceMode] || [];
  if (!filter || source.length === 0) return [];

  const existing = new Set(current.map((problem) => normalize(problem.question)));
  return source.filter((problem) => {
    if (existing.has(normalize(problem.question))) return false;
    const haystack = normalize(`${problem.question} ${problem.answer} ${problem.hint || ''}`);
    const includes = filter.include.some((keyword) => haystack.includes(normalize(keyword)));
    const excludes = (filter.exclude || []).some((keyword) => haystack.includes(normalize(keyword)));
    return includes && !excludes;
  });
};

const expandUnitProblems = (mode: string, sourceMode: string, unitName: string): GeneralProblem[] => {
  const seeds = SCIENCE_UNIT_SEED_DATA[mode] || [];
  const extras = SCIENCE_UNIT_EXTRA_DATA[mode] || [];
  const more = SCIENCE_UNIT_MORE_DATA[mode] || [];
  const base = dedupeByQuestion([...seeds, ...extras, ...more]);
  if (base.length >= SCIENCE_UNIT_TARGET_COUNT) return base.slice(0, SCIENCE_UNIT_TARGET_COUNT);

  const candidates = getSourceCandidates(mode, sourceMode, base);
  return dedupeByQuestion([...base, ...candidates]).slice(0, SCIENCE_UNIT_TARGET_COUNT);
};

const getGradeFromMode = (mode: string): number => {
  const lifeMatch = mode.match(/^LIFE_(\d+)_/);
  if (lifeMatch) return Number(lifeMatch[1]);
  const scienceMatch = mode.match(/^SCIENCE_(\d+)_/);
  if (scienceMatch) return Number(scienceMatch[1]);
  return 9;
};

const replaceAll = (text: string, replacements: Array<[string, string]>): string =>
  replacements.reduce((current, [from, to]) => current.split(from).join(to), text);

